package com.timedtiles;

/** What {@link MarkerBook#placeMine} did: a marker was added or removed. */
public final class Change
{
	/** The two things a click can do. */
	public enum Type
	{
		ADD,
		REMOVE
	}

	private final Type type;
	private final Marker marker;

	public Change(Type type, Marker marker)
	{
		this.type = type;
		this.marker = marker;
	}

	public Type getType()
	{
		return type;
	}

	public Marker getMarker()
	{
		return marker;
	}
}

package com.timedtiles;

/** When a left click places a marker instead of walking. */
public final class ClickRule
{
	private ClickRule()
	{
	}

	/** True only when the key is held, no menu is open, "Walk here" is in the menu and a tile was found. */
	public static boolean shouldPlace(boolean keyHeld, boolean menuOpen, boolean hasWalkHere, boolean tileFound)
	{
		return keyHeld && !menuOpen && hasWalkHere && tileFound;
	}
}

package com.timedtiles;

import java.awt.Polygon;
import java.awt.geom.Path2D;

/**
 * The sums behind the clock styles: how much of a marker's time is left, where a tile's middle and its top-right
 * corner are on screen, and the part of its outline that is still to run. Plain numbers and AWT shapes, so it needs
 * no game client.
 */
public final class ClockFace
{
	private ClockFace()
	{
	}

	/** The share of its life a marker has left, 0 to 1. A life of 0 or less counts as none left. */
	public static float timeLeft(long remainingMs, long lifeMs)
	{
		if (lifeMs <= 0)
		{
			return 0f;
		}
		return (float) Math.max(0.0, Math.min(1.0, remainingMs / (double) lifeMs));
	}

	/** The average of the polygon's corners: {x, y}. */
	public static double[] centre(Polygon p)
	{
		double x = 0;
		double y = 0;
		for (int i = 0; i < p.npoints; i++)
		{
			x += p.xpoints[i];
			y += p.ypoints[i];
		}
		return new double[]{x / Math.max(1, p.npoints), y / Math.max(1, p.npoints)};
	}

	/** The index of the corner furthest up and to the right on screen (the largest x minus y). */
	public static int topRight(Polygon p)
	{
		int best = 0;
		for (int i = 1; i < p.npoints; i++)
		{
			if (p.xpoints[i] - p.ypoints[i] > p.xpoints[best] - p.ypoints[best])
			{
				best = i;
			}
		}
		return best;
	}

	/**
	 * The first {@code share} of the polygon's outline, walked from its top-left corner (the smallest x plus y) in
	 * the order of its points. Empty for a share of 0 or less, the whole closed outline for 1 or more.
	 */
	public static Path2D.Double outlinePart(Polygon p, float share)
	{
		final Path2D.Double path = new Path2D.Double();
		final int n = p.npoints;
		if (n < 2 || share <= 0f)
		{
			return path;
		}
		int start = 0;
		for (int i = 1; i < n; i++)
		{
			if (p.xpoints[i] + p.ypoints[i] < p.xpoints[start] + p.ypoints[start])
			{
				start = i;
			}
		}
		double total = 0;
		for (int i = 0; i < n; i++)
		{
			total += edge(p, (start + i) % n);
		}
		double left = Math.min(1.0, share) * total;
		path.moveTo(p.xpoints[start], p.ypoints[start]);
		for (int i = 0; i < n && left > 0; i++)
		{
			final int a = (start + i) % n;
			final int b = (a + 1) % n;
			final double len = edge(p, a);
			final double t = len <= 0 ? 1.0 : Math.min(1.0, left / len);
			path.lineTo(p.xpoints[a] + (p.xpoints[b] - p.xpoints[a]) * t, p.ypoints[a] + (p.ypoints[b] - p.ypoints[a]) * t);
			left -= len;
		}
		return path;
	}

	private static double edge(Polygon p, int a)
	{
		final int b = (a + 1) % p.npoints;
		return Math.hypot(p.xpoints[b] - p.xpoints[a], p.ypoints[b] - p.ypoints[a]);
	}
}

package com.timedtiles;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;

/**
 * The 2hBuilds coin, the family mark every 2hBuilds plugin carries in the top-left corner of its sidebar icon: a
 * hammered gold disc 9 px across with its "2h" struck in dark brown, drawn in code so it needs no image file. It is
 * the coin half of {@link NavIcon}, pulled out so the one picture can be copied into another plugin's package
 * unchanged - it refers to nothing of this plugin's and to no class but the JDK's.
 *
 * <p>{@link #paint} draws it where it sits in a 16 x 16 icon, the disc centred on (4.5, 4.5): three jittered discs
 * with antialiasing on, then the two letters crisp on top, antialiasing off again, so a caller that draws more on
 * the same {@link Graphics2D} afterwards gets the hint it had not set itself.
 */
final class CoinGlyph
{
	private static final Color RIM = new Color(88, 62, 16);
	private static final Color EDGE = new Color(140, 102, 30);
	private static final Color FACE = new Color(196, 156, 58);
	private static final Color INK = new Color(52, 36, 8);

	/** The coin's centre and the three radii of its rim, edge and face. */
	private static final double COIN_X = 4.5, COIN_Y = 4.5;
	private static final double[] RADII = {4.7, 3.9, 3.3};
	private static final Color[] RINGS = {RIM, EDGE, FACE};
	/** The hammering: one offset per sixteenth of the edge. */
	private static final double[] JITTER = {0.3, -0.2, 0.4, 0.1, -0.3, 0.2, 0.4, -0.1, 0.2, -0.4, 0.3, 0.0, -0.3, 0.4, -0.1, 0.2};

	/** The letters, one character a pixel: "2" then "h", 3 wide and 5 tall each, a 1 px gap between. */
	private static final String[] TWO = {"###", "..#", "###", "#..", "###"};
	private static final String[] H = {"#..", "#..", "###", "#.#", "#.#"};
	private static final int LETTERS_X = 1, LETTERS_Y = 2;

	private CoinGlyph()
	{
	}

	/**
	 * Draws the coin in the top-left of the 16 x 16 icon {@code g} paints on: three jittered discs with
	 * antialiasing, then the letters crisp on top. Leaves the antialiasing hint off and the colour at the letters'
	 * ink.
	 */
	static void paint(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		for (int i = 0; i < RADII.length; i++)
		{
			g.setColor(RINGS[i]);
			g.fill(coin(RADII[i]));
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		glyph(g, TWO, LETTERS_X, LETTERS_Y);
		glyph(g, H, LETTERS_X + 4, LETTERS_Y);
	}

	private static Path2D coin(double radius)
	{
		final Path2D path = new Path2D.Double();
		for (int i = 0; i < JITTER.length; i++)
		{
			final double angle = i * Math.PI * 2 / JITTER.length;
			final double r = radius + JITTER[i];
			final double x = COIN_X + Math.cos(angle) * r;
			final double y = COIN_Y + Math.sin(angle) * r;
			if (i == 0)
			{
				path.moveTo(x, y);
			}
			else
			{
				path.lineTo(x, y);
			}
		}
		path.closePath();
		return path;
	}

	private static void glyph(Graphics2D g, String[] rows, int x, int y)
	{
		g.setColor(INK);
		for (int r = 0; r < rows.length; r++)
		{
			for (int c = 0; c < rows[r].length(); c++)
			{
				if (rows[r].charAt(c) == '#')
				{
					g.fillRect(x + c, y + r, 1, 1);
				}
			}
		}
	}
}

package com.timedtiles;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;

/**
 * The 2hBuilds settings icon, drawn in code: a ring with eight teeth and a hole through the middle, the picture the
 * settings icon of every 2hBuilds plugin shows (STANDARD A4). It is the bank's icon, pulled out of its widget helper so
 * the one picture can be copied into another plugin unchanged; it refers to no class of the plugin it sits in.
 *
 * <p>The ring is a stroke and not a filled disc, so the middle stays transparent and the picture reads as a settings
 * icon at 12 px rather than as a cogged blob. The teeth are eight round-capped spokes every 45 degrees, starting on
 * the ring's own circle so each is rooted in the ring's metal and none reaches into the hole. Every length is a
 * fraction of the size, so the same shape comes out at any size.
 */
final class GearGlyph
{
	/** The number of teeth. */
	static final int TEETH = 8;
	/** The smallest side drawn: below it the hole closes and the teeth merge. */
	static final int MIN_SIZE = 7;

	private GearGlyph()
	{
	}

	/**
	 * A new square icon, transparent except for the ring and its teeth.
	 *
	 * @param size   the icon's side in px; anything under {@value #MIN_SIZE} is raised to it
	 * @param colour the ink; null falls back to the sidebar's quiet grey, {@link ColorScheme#LIGHT_GRAY_COLOR}
	 */
	static ImageIcon icon(int size, Color colour)
	{
		final int s = Math.max(MIN_SIZE, size);
		final BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			g.setColor(colour == null ? ColorScheme.LIGHT_GRAY_COLOR : colour);
			final double centre = s / 2.0;
			// The ring's centre line, the width of its metal, and how far a tooth's centre line reaches - the last
			// one pulled in by half a tooth so the round cap lands inside the icon instead of being clipped.
			final double ring = centre * 0.52;
			final float ringWidth = (float) Math.max(1.5, s * 0.2);
			final float toothWidth = (float) Math.max(1.3, s * 0.16);
			final double toothOut = centre - toothWidth / 2.0 - 0.25;
			g.setStroke(new BasicStroke(ringWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.draw(new Ellipse2D.Double(centre - ring, centre - ring, ring * 2.0, ring * 2.0));
			g.setStroke(new BasicStroke(toothWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			for (int i = 0; i < TEETH; i++)
			{
				final double angle = i * 2.0 * Math.PI / TEETH;
				final double cos = Math.cos(angle);
				final double sin = Math.sin(angle);
				g.draw(new Line2D.Double(centre + cos * ring, centre + sin * ring,
					centre + cos * toothOut, centre + sin * toothOut));
			}
		}
		finally
		{
			g.dispose();
		}
		return new ImageIcon(img);
	}
}

package com.timedtiles;

/**
 * The text drawn on a marker's tile for each {@link TileLabel}. Plain numbers in, a string out, so it needs no game client.
 */
public final class LabelText
{
	/** The most decimals the timer can show. */
	public static final int MAX_DECIMALS = 2;

	private LabelText()
	{
	}

	/**
	 * The text for one marker, or null when nothing is drawn.
	 *
	 * @param mode null is treated as {@link TileLabel#NUMBER}, as a setting RuneLite could not read
	 * @param who the placer's name for a party marker, null for the player's own
	 * @param remainingMs time left on the marker
	 * @param decimals digits after the point for the timer, 0 to {@link #MAX_DECIMALS}
	 */
	public static String of(TileLabel mode, int number, String who, boolean showNames, long remainingMs, int decimals)
	{
		final String main;
		switch ((mode == null ? TileLabel.NUMBER : mode).words())
		{
			case NUMBER:
				main = Integer.toString(number);
				break;
			case TIMER:
				main = seconds(remainingMs, decimals);
				break;
			default:
				return null;
		}
		return who != null && showNames ? main + " " + who : main;
	}

	/**
	 * Seconds left, rounded up at the shown digit so the timer never reads zero while the marker is still there:
	 * 3.84 s is "4", "3.9" or "3.84". Not below zero.
	 */
	public static String seconds(long remainingMs, int decimals)
	{
		final int d = Math.max(0, Math.min(MAX_DECIMALS, decimals));
		final long unitMs = d == 2 ? 10 : d == 1 ? 100 : 1000;
		final long units = Math.max(0, (Math.max(0, remainingMs) + unitMs - 1) / unitMs);
		if (d == 0)
		{
			return Long.toString(units);
		}
		final long scale = d == 2 ? 100 : 10;
		final long fraction = units % scale;
		return (units / scale) + "." + (d == 2 && fraction < 10 ? "0" : "") + fraction;
	}
}

package com.timedtiles;

/**
 * One tile marker. Immutable. Plain ints and longs, so it needs no game client: {@code owner} is 0 for the player's
 * own marker and a party member's id otherwise, {@code who} is null for the player's own, and {@code rgb} is 24-bit.
 */
public final class Marker
{
	private final long owner;
	private final String who;
	private final int x;
	private final int y;
	private final int plane;
	private final int number;
	private final int rgb;
	private final long createdMs;
	private final long lifeMs;

	public Marker(long owner, String who, int x, int y, int plane, int number, int rgb, long createdMs, long lifeMs)
	{
		this.owner = owner;
		this.who = who;
		this.x = x;
		this.y = y;
		this.plane = plane;
		this.number = number;
		this.rgb = rgb;
		this.createdMs = createdMs;
		this.lifeMs = lifeMs;
	}

	public long getOwner()
	{
		return owner;
	}

	public String getWho()
	{
		return who;
	}

	public int getX()
	{
		return x;
	}

	public int getY()
	{
		return y;
	}

	public int getPlane()
	{
		return plane;
	}

	public int getNumber()
	{
		return number;
	}

	public int getRgb()
	{
		return rgb;
	}

	public long getCreatedMs()
	{
		return createdMs;
	}

	public long getLifeMs()
	{
		return lifeMs;
	}

	/** The moment this marker is gone: created plus life. */
	public long expiresAtMs()
	{
		return createdMs + lifeMs;
	}

	boolean sameTile(int x, int y, int plane)
	{
		return this.x == x && this.y == y && this.plane == plane;
	}
}

package com.timedtiles;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import java.util.ListIterator;
import javax.inject.Singleton;

/**
 * Every marker on screen: the player's own and the party's. Used only on the client thread, so it has no locks.
 */
@Singleton
public final class MarkerBook
{
	/** Party message types, as {@link TimedTilesMessage} carries them. */
	public static final int TYPE_ADD = 0;
	public static final int TYPE_REMOVE = 1;
	public static final int TYPE_CLEAR = 2;

	/** The most markers one owner has at once; one more removes the oldest. */
	public static final int MAX_PER_OWNER = 20;

	/** The longest life a party member can give a marker of theirs, in seconds. */
	private static final int MAX_SECONDS = 120;

	/** The player's markers, oldest first. */
	private final List<Marker> mine = new ArrayList<>();

	/** Party markers, oldest first. */
	private final List<Marker> party = new ArrayList<>();

	private int counter;

	/** The sample marker shown after a look setting changes, or null. Never shared, never numbered with the player's. */
	private Marker preview;

	/** Shows a sample marker numbered 1 on a tile, in place of any earlier one, so the player sees a new look at once. */
	public void showPreview(int x, int y, int plane, int rgb, long nowMs, long lifeMs)
	{
		preview = new Marker(0, null, x, y, plane, 1, rgb & 0xFFFFFF, nowMs, lifeMs);
	}

	/**
	 * The player clicked a tile: remove their marker there, or add one with the next number.
	 */
	public Change placeMine(int x, int y, int plane, int rgb, long nowMs, long lifeMs)
	{
		expire(nowMs);
		for (Iterator<Marker> it = mine.iterator(); it.hasNext(); )
		{
			final Marker m = it.next();
			if (m.sameTile(x, y, plane))
			{
				it.remove();
				return new Change(Change.Type.REMOVE, m);
			}
		}
		if (mine.isEmpty())
		{
			counter = 0;
		}
		counter++;
		final Marker marker = new Marker(0, null, x, y, plane, counter, rgb & 0xFFFFFF, nowMs, lifeMs);
		mine.add(marker);
		if (mine.size() > MAX_PER_OWNER)
		{
			mine.remove(0);
		}
		return new Change(Change.Type.ADD, marker);
	}

	/** Removes all the player's markers; true if there were any. */
	public boolean clearMine()
	{
		final boolean any = !mine.isEmpty();
		mine.clear();
		preview = null;
		return any;
	}

	/**
	 * A party member's message. Never touches the player's own markers.
	 */
	public void applyParty(long member, String who, int type, int x, int y, int plane, int number, int rgb,
		int seconds, long nowMs)
	{
		expire(nowMs);
		if (who != null)
		{
			nameMember(member, who);
		}
		if (type == TYPE_CLEAR)
		{
			dropMember(member);
			return;
		}
		party.removeIf(m -> m.getOwner() == member && m.sameTile(x, y, plane));
		if (type != TYPE_ADD)
		{
			return;
		}
		final long lifeMs = Math.max(1, Math.min(MAX_SECONDS, seconds)) * 1000L;
		party.add(new Marker(member, who, x, y, plane, number, rgb & 0xFFFFFF, nowMs, lifeMs));
		int count = 0;
		for (Marker m : party)
		{
			if (m.getOwner() == member)
			{
				count++;
			}
		}
		for (Iterator<Marker> it = party.iterator(); it.hasNext() && count > MAX_PER_OWNER; )
		{
			if (it.next().getOwner() == member)
			{
				it.remove();
				count--;
			}
		}
	}

	/** Gives a member's markers that have no name yet (the sender was not in the party list at the time) theirs. */
	private void nameMember(long member, String who)
	{
		for (ListIterator<Marker> it = party.listIterator(); it.hasNext(); )
		{
			final Marker m = it.next();
			if (m.getOwner() == member && m.getWho() == null)
			{
				it.set(new Marker(member, who, m.getX(), m.getY(), m.getPlane(), m.getNumber(), m.getRgb(),
					m.getCreatedMs(), m.getLifeMs()));
			}
		}
	}

	/** Removes one party member's markers. */
	public void dropMember(long member)
	{
		party.removeIf(m -> m.getOwner() == member);
	}

	/** Removes every party marker, keeps the player's. */
	public void dropParty()
	{
		party.clear();
	}

	/** Removes everything. */
	public void dropAll()
	{
		mine.clear();
		party.clear();
		preview = null;
		counter = 0;
	}

	/** Removes every marker whose time has come. */
	public void expire(long nowMs)
	{
		mine.removeIf(m -> nowMs >= m.expiresAtMs());
		party.removeIf(m -> nowMs >= m.expiresAtMs());
		if (preview != null && nowMs >= preview.expiresAtMs())
		{
			preview = null;
		}
	}

	/**
	 * The unexpired markers on a plane: the player's by number, then the party's by creation time, then the sample
	 * marker.
	 */
	public List<Marker> visible(int plane, long nowMs)
	{
		final List<Marker> own = new ArrayList<>();
		for (Marker m : mine)
		{
			if (m.getPlane() == plane && nowMs < m.expiresAtMs())
			{
				own.add(m);
			}
		}
		own.sort(Comparator.comparingInt(Marker::getNumber));
		final List<Marker> others = new ArrayList<>();
		for (Marker m : party)
		{
			if (m.getPlane() == plane && nowMs < m.expiresAtMs())
			{
				others.add(m);
			}
		}
		others.sort(Comparator.comparingLong(Marker::getCreatedMs));
		own.addAll(others);
		if (preview != null && preview.getPlane() == plane && nowMs < preview.expiresAtMs())
		{
			own.add(preview);
		}
		return own;
	}

	/**
	 * 1 until the fade starts, then straight down to 0 at expiry; the fade is the last {@code fadeMs} (all of a shorter
	 * life). A fade of 0 stays solid until the marker is gone.
	 */
	public static float alpha(Marker m, long nowMs, long fadeMs)
	{
		if (fadeMs <= 0)
		{
			return nowMs < m.expiresAtMs() ? 1f : 0f;
		}
		final long fade = Math.min(fadeMs, m.getLifeMs());
		if (fade <= 0)
		{
			return 0f;
		}
		final float a = (m.expiresAtMs() - nowMs) / (float) fade;
		return Math.max(0f, Math.min(1f, a));
	}

	/** For each marker, how many earlier ones in the list share its tile. */
	public static int[] stackIndex(List<Marker> visible)
	{
		final int[] stack = new int[visible.size()];
		for (int i = 0; i < stack.length; i++)
		{
			final Marker m = visible.get(i);
			for (int j = 0; j < i; j++)
			{
				if (visible.get(j).sameTile(m.getX(), m.getY(), m.getPlane()))
				{
					stack[i]++;
				}
			}
		}
		return stack;
	}
}

package com.timedtiles;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Draws the markers: a tile outline in the marker's colour ("Outline thickness") with a fill of "Tile fill" percent,
 * fading out over "Fade time" at the end of its life, with the clock "Tile shows" picks showing the share of its time
 * left, and the words it picks over it - its number, its seconds left or nothing - and the placer's name for a party
 * marker when "Show names" is on. The clock and the words take the colour "Timer & number" picks (the marker's
 * by default); the outline and fill always keep the marker's. Runs on the client thread.
 */
public class MarkerOverlay extends Overlay
{
	private static final int STACK_STEP_PX = 16;
	private static final float LARGE_FONT_SIZE = 24f;
	private static final long ECHO_MS = 1500;
	private static final int MIN_WIDTH = 1;
	private static final int MAX_WIDTH = 6;
	private static final Stroke ECHO_STROKE = new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f,
		new float[]{4f, 4f}, 0f);

	private final Client client;
	private final TimedTilesConfig config;
	private final MarkerBook book;

	/** The outline stroke, rebuilt only when the thickness setting changes. */
	private Stroke border = new BasicStroke(2);
	private int borderWidth = 2;

	/** Developer-mode rings: {x, y, plane, until}. */
	private final List<long[]> echoes = new ArrayList<>();

	@Inject
	private MarkerOverlay(Client client, TimedTilesConfig config, MarkerBook book)
	{
		this.client = client;
		this.config = config;
		this.book = book;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	/** A dashed ring on a tile for 1.5 s: the developer-mode sign that a message came back from the party server. */
	void addEcho(int x, int y, int plane, long nowMs)
	{
		echoes.add(new long[]{x, y, plane, nowMs + ECHO_MS});
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		final long now = System.currentTimeMillis();
		book.expire(now);
		final int width = Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, config.outlineWidth()));
		if (width != borderWidth)
		{
			borderWidth = width;
			border = new BasicStroke(width);
		}
		final int plane = client.getPlane();
		final List<Marker> visible = book.visible(plane, now);
		if (!visible.isEmpty())
		{
			final int[] stack = MarkerBook.stackIndex(visible);
			final Font before = g.getFont();
			g.setFont(config.largeNumbers()
				? FontManager.getRunescapeBoldFont().deriveFont(LARGE_FONT_SIZE)
				: FontManager.getRunescapeBoldFont());
			for (int i = 0; i < visible.size(); i++)
			{
				drawMarker(g, visible.get(i), stack[i], now);
			}
			g.setFont(before);
		}
		drawEchoes(g, plane, now);
		return null;
	}

	private void drawMarker(Graphics2D g, Marker m, int stacked, long now)
	{
		final float a = MarkerBook.alpha(m, now, config.fadeSeconds() * 1000L);
		if (a <= 0f)
		{
			return;
		}
		final LocalPoint lp = LocalPoint.fromWorld(client, new WorldPoint(m.getX(), m.getY(), m.getPlane()));
		if (lp == null)
		{
			return;
		}
		final Polygon poly = Perspective.getCanvasTilePoly(client, lp);
		if (poly == null)
		{
			return;
		}
		final TileLabel shows = config.tileLabel();
		final int detail = NumberColour.of(config.numberColour(), config.customColour(), m.getRgb());
		MarkerPainter.tile(g, poly, m.getRgb(), a, config.tileFill(), border, borderWidth,
			shows == null ? ClockStyle.OFF : shows.clock(), ClockFace.timeLeft(m.expiresAtMs() - now, m.getLifeMs()),
			detail);
		final String label = LabelText.of(shows, m.getNumber(), m.getWho(), config.showNames(),
			m.expiresAtMs() - now, config.timerDecimals());
		if (label == null)
		{
			return;
		}
		final Point at = Perspective.getCanvasTextLocation(client, g, lp, label, 0);
		if (at != null)
		{
			// Drawn by the painter and not by OverlayUtil.renderTextLocation, whose shadow would not fade with the marker.
			MarkerPainter.label(g, label, at.getX(), at.getY() - stacked * STACK_STEP_PX, detail, a);
		}
	}

	private void drawEchoes(Graphics2D g, int plane, long now)
	{
		for (Iterator<long[]> it = echoes.iterator(); it.hasNext(); )
		{
			final long[] echo = it.next();
			if (now >= echo[3])
			{
				it.remove();
				continue;
			}
			if (echo[2] != plane)
			{
				continue;
			}
			final LocalPoint lp = LocalPoint.fromWorld(client, new WorldPoint((int) echo[0], (int) echo[1], plane));
			if (lp == null)
			{
				continue;
			}
			final Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly != null)
			{
				OverlayUtil.renderPolygon(g, poly, Color.WHITE, ECHO_STROKE);
			}
		}
	}

}

package com.timedtiles;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Paints one marker onto a tile's screen polygon: its outline and fill, its clock, and its label. The overlay calls it
 * with the game's tile; the menu pictures beside each "Tile shows" choice were drawn with it too, so they look as the
 * markers do in game. Needs no game client.
 */
public final class MarkerPainter
{
	/** The clock's radius as a share of the tile's smaller side on screen, and the smallest it is drawn. */
	private static final double CLOCK_SIZE = 0.28;
	private static final double MIN_CLOCK_RADIUS = 3;
	/** How far the corner clock sits in from the tile's top-right corner, as a share of the way to its middle. */
	private static final double CORNER_INSET = 0.38;
	/** The faint parts of a clock (its face, the spent outline), as a share of the marker's opacity. */
	private static final float FAINT = 0.3f;
	private static final float SWEEP_ALPHA = 0.45f;

	private MarkerPainter()
	{
	}

	/**
	 * The tile and its clock.
	 *
	 * @param a           the marker's fade, 0 to 1
	 * @param fillPercent "Tile fill", 0 to 100
	 * @param border      the outline stroke, {@code borderWidth} pixels wide
	 * @param left        the share of its time the marker has left, 0 to 1
	 * @param clockRgb    the clock's colour: the marker's, or the one "Timer & number" picks
	 */
	public static void tile(Graphics2D g, Polygon poly, int rgb, float a, int fillPercent, Stroke border,
		int borderWidth, ClockStyle clock, float left, int clockRgb)
	{
		final Color fill = withAlpha(rgb, a * 255 * fillPercent / 100f);
		final Color outline = withAlpha(rgb, a * 255 * (clock == ClockStyle.BORDER ? FAINT : 1f));
		OverlayUtil.renderPolygon(g, poly, outline, fill, border);
		if (clock != null && clock != ClockStyle.OFF)
		{
			clock(g, poly, clock, left, clockRgb, a, borderWidth);
		}
	}

	/** The label with a black shadow, both fading with the marker; (x, y) is the text's baseline start. */
	public static void label(Graphics2D g, String text, int x, int y, int rgb, float a)
	{
		final Color colour = withAlpha(rgb, a * 255);
		g.setColor(new Color(0, 0, 0, colour.getAlpha()));
		g.drawString(text, x + 1, y + 1);
		g.setColor(colour);
		g.drawString(text, x, y);
	}

	private static void clock(Graphics2D g, Polygon poly, ClockStyle clock, float left, int rgb, float a,
		int borderWidth)
	{
		final Object smooth = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		final Stroke stroke = g.getStroke();
		final Shape clip = g.getClip();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		final double[] c = ClockFace.centre(poly);
		final Rectangle box = poly.getBounds();
		final double r = Math.max(MIN_CLOCK_RADIUS, Math.min(box.width, box.height) * CLOCK_SIZE);
		final double sweep = -360.0 * left;
		final Color solid = withAlpha(rgb, a * 255);
		final Color faint = withAlpha(rgb, a * 255 * FAINT);
		switch (clock)
		{
			case PIE:
				g.setColor(faint);
				g.fill(new Ellipse2D.Double(c[0] - r, c[1] - r, 2 * r, 2 * r));
				g.setColor(solid);
				g.fill(new Arc2D.Double(c[0] - r, c[1] - r, 2 * r, 2 * r, 90, sweep, Arc2D.PIE));
				break;
			case RING:
				g.setStroke(new BasicStroke((float) Math.max(2.0, r * 0.35), BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND));
				g.setColor(faint);
				g.draw(new Ellipse2D.Double(c[0] - r, c[1] - r, 2 * r, 2 * r));
				g.setColor(solid);
				g.draw(new Arc2D.Double(c[0] - r, c[1] - r, 2 * r, 2 * r, 90, sweep, Arc2D.OPEN));
				break;
			case BORDER:
				g.setStroke(new BasicStroke(borderWidth + 1, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.setColor(solid);
				g.draw(ClockFace.outlinePart(poly, left));
				break;
			case SWEEP:
				final double big = Math.max(box.width, box.height);
				g.clip(poly);
				g.setColor(withAlpha(rgb, a * 255 * SWEEP_ALPHA));
				g.fill(new Arc2D.Double(c[0] - big, c[1] - big, 2 * big, 2 * big, 90, sweep, Arc2D.PIE));
				break;
			case CORNER:
				final int k = ClockFace.topRight(poly);
				final double x = poly.xpoints[k] + (c[0] - poly.xpoints[k]) * CORNER_INSET;
				final double y = poly.ypoints[k] + (c[1] - poly.ypoints[k]) * CORNER_INSET;
				final double cr = Math.max(MIN_CLOCK_RADIUS, r * 0.55);
				g.setColor(new Color(0, 0, 0, Math.round(a * 150)));
				g.fill(new Ellipse2D.Double(x - cr - 1, y - cr - 1, 2 * cr + 2, 2 * cr + 2));
				g.setColor(solid);
				g.fill(new Arc2D.Double(x - cr, y - cr, 2 * cr, 2 * cr, 90, sweep, Arc2D.PIE));
				break;
			default:
				break;
		}
		g.setClip(clip);
		g.setStroke(stroke);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, smooth);
	}

	private static Color withAlpha(int rgb, float alpha)
	{
		return new Color((rgb >> 16) & 0xFF, (rgb >> 8) & 0xFF, rgb & 0xFF,
			Math.max(0, Math.min(255, Math.round(alpha))));
	}
}

package com.timedtiles;

import java.net.URL;

/**
 * The text of one choice in a settings dropdown, with a picture of what it looks like in front. RuneLite's dropdown is
 * a Swing label showing each choice's {@code toString()}, and a Swing label draws HTML, so the picture is an
 * {@code <img>} of the plugin's own resource. When the picture cannot be found, the plain text is used.
 *
 * <p>The pictures are 48 x 32, a marker at game scale, drawn by {@link MarkerPainter} (docs/menu-icons/RealIcons.java.txt in the private repository).
 * The opened list's rows grow to fit them; the closed box stays 22 px tall and shows the middle of the picture.
 */
final class MenuText
{
	static final int WIDTH = 48;
	static final int HEIGHT = 32;

	private MenuText()
	{
	}

	/**
	 * @param icon the picture's name in {@code com/timedtiles/menu/}, without ".png"
	 * @param text the choice's name, shown after the picture
	 */
	static String with(String icon, String text)
	{
		final URL url = MenuText.class.getResource("menu/" + icon + ".png");
		if (url == null)
		{
			return text;
		}
		return "<html><img src='" + url + "' width='" + WIDTH + "' height='" + HEIGHT + "' align='middle'>&nbsp;" + text
			+ "</html>";
	}

	/** The colour squares' size. */
	static final int SQUARE = 12;

	/**
	 * A choice with a {@value #SQUARE} px square in front: a table cell of {@code rgb} holding the picture {@code icon}
	 * (a grey frame with a clear middle), or the picture alone when {@code rgb} is negative. A table keeps every square
	 * the same size and level with the words in any font; a coloured run of spaces would take the font's width, which
	 * in the RuneScape font is a thin bar.
	 */
	static String withSquare(int rgb, String icon, String text)
	{
		final URL url = MenuText.class.getResource("menu/" + icon + ".png");
		if (url == null)
		{
			return text;
		}
		final String cell = rgb < 0
			? "<td valign='middle'>"
			: String.format("<td valign='middle' bgcolor='#%06X'>", rgb & 0xFFFFFF);
		return "<html><table cellspacing='0' cellpadding='0'><tr><td valign='middle'>"
			+ "<table cellspacing='0' cellpadding='0'><tr>" + cell + "<img src='" + url + "' width='" + SQUARE
			+ "' height='" + SQUARE + "'></td></tr></table></td><td valign='middle'>&nbsp;" + text
			+ "</td></tr></table></html>";
	}
}

package com.timedtiles;

import java.awt.Color;

/**
 * The "Timer & number" choices: the colour of each marker's timer, number, clock and name. "Marker colour" keeps the
 * marker's own colour; the others draw every marker's in one colour, easier to read on a busy floor; "Custom" uses the
 * "Custom colour" picker. The tile's outline and fill always keep the marker's colour. Each choice shows a small
 * colour square in the dropdown ({@link MenuText#withSquare}); Custom's shows the Custom colour now.
 */
public enum NumberColour
{
	MARKER("Marker colour", -1),
	WHITE("White", 0xFFFFFF),
	BLACK("Black", 0x000000),
	YELLOW("Yellow", 0xFFFF00),
	CYAN("Cyan", 0x00FFFF),
	GREEN("Green", 0x00FF00),
	PINK("Pink", 0xFF69B4),
	CUSTOM("Custom", -1);

	/** The grey frame drawn over every colour square; Marker colour has its own picture, a gold tile outline. */
	static final String FRAME = "colour-frame";
	static final String MARKER_PICTURE = "colour-marker";

	/**
	 * The "Custom colour" now, as 0xRRGGBB, so Custom's square in the dropdown shows it. Set by the plugin at start-up
	 * and whenever the colour changes; the dropdown asks each choice for its text every time it draws.
	 */
	private static volatile int customRgb = 0xB478FF;

	/** Custom's square shows {@code colour} from now on; null is ignored. */
	static void showCustom(Color colour)
	{
		if (colour != null)
		{
			customRgb = colour.getRGB() & 0xFFFFFF;
		}
	}

	/** The fixed colour as 0xRRGGBB, or -1 for Marker colour and Custom. */
	private final int rgb;
	private final String text;
	private final String menu;

	NumberColour(String text, int rgb)
	{
		this.rgb = rgb;
		this.text = text;
		this.menu = rgb < 0
			? MenuText.withSquare(-1, MARKER_PICTURE, text)
			: MenuText.withSquare(rgb, FRAME, text);
	}

	/**
	 * The colour as 0xRRGGBB for a marker of {@code markerRgb}. A setting RuneLite could not read, or a Custom with no
	 * colour, keeps the marker's.
	 */
	public static int of(NumberColour choice, Color custom, int markerRgb)
	{
		if (choice == null || choice == MARKER)
		{
			return markerRgb;
		}
		if (choice == CUSTOM)
		{
			return custom == null ? markerRgb : custom.getRGB() & 0xFFFFFF;
		}
		return choice.rgb;
	}

	@Override
	public String toString()
	{
		return this == CUSTOM ? MenuText.withSquare(customRgb, FRAME, text) : menu;
	}
}

package com.timedtiles;

import java.util.HashMap;
import java.util.Map;

/**
 * Keeps each party member's markers in a colour you can tell apart: the colour they chose, unless it is too close to
 * yours or to another member's, in which case a stand-in that is clear of them all (the one they already had, if it
 * still is, otherwise the first free palette colour). It is decided again at every marker, so a member who changes
 * their colour is shown in it as soon as it no longer clashes. Plain ints, no game client; client thread only.
 */
public final class PartyColours
{
	/** Colours closer than this (straight-line distance in RGB) look the same on screen. */
	private static final int TOO_CLOSE = 30;

	private static final int[] PALETTE = {
		0x00C8FF, // cyan
		0xFF40C0, // pink
		0x40FF40, // green
		0xA064FF, // violet
		0xFF6030, // red-orange
		0xFFFFFF, // white
	};

	private final Map<Long, Integer> assigned = new HashMap<>();

	/** The colour to draw this member's markers in. */
	public int colourFor(long member, int sentRgb, int myRgb)
	{
		final int sent = sentRgb & 0xFFFFFF;
		int chosen = sent;
		if (clashes(sent, member, myRgb))
		{
			final Integer known = assigned.get(member);
			if (known != null && !clashes(known, member, myRgb))
			{
				chosen = known;
			}
			else
			{
				for (int candidate : PALETTE)
				{
					if (!clashes(candidate, member, myRgb))
					{
						chosen = candidate;
						break;
					}
				}
			}
		}
		assigned.put(member, chosen);
		return chosen;
	}

	public void forget(long member)
	{
		assigned.remove(member);
	}

	public void clear()
	{
		assigned.clear();
	}

	private boolean clashes(int rgb, long member, int myRgb)
	{
		if (close(rgb, myRgb))
		{
			return true;
		}
		for (Map.Entry<Long, Integer> other : assigned.entrySet())
		{
			if (other.getKey() != member && close(rgb, other.getValue()))
			{
				return true;
			}
		}
		return false;
	}

	static boolean close(int a, int b)
	{
		final int dr = ((a >> 16) & 0xFF) - ((b >> 16) & 0xFF);
		final int dg = ((a >> 8) & 0xFF) - ((b >> 8) & 0xFF);
		final int db = (a & 0xFF) - (b & 0xFF);
		return dr * dr + dg * dg + db * db < TOO_CLOSE * TOO_CLOSE;
	}
}

package com.timedtiles;

import java.util.Collection;
import net.runelite.api.WorldType;

/** Which worlds count as PvP for sharing. */
public final class PvpWorlds
{
	private PvpWorlds()
	{
	}

	public static boolean isPvp(Collection<WorldType> types)
	{
		return WorldType.isPvpWorld(types)
			|| types.contains(WorldType.DEADMAN)
			|| types.contains(WorldType.PVP_ARENA)
			|| types.contains(WorldType.LAST_MAN_STANDING)
			|| types.contains(WorldType.BOUNTY)
			|| types.contains(WorldType.HIGH_RISK);
	}
}

package com.timedtiles;

/** When the player's markers are sent to the party. */
public final class ShareRule
{
	private ShareRule()
	{
	}

	/** True only when sharing is on, the player is in a party, not in the Wilderness and not on a PvP world. */
	public static boolean canShare(boolean shareOn, boolean inParty, boolean inWilderness, boolean pvpWorld)
	{
		return shareOn && inParty && !inWilderness && !pvpWorld;
	}
}

